public function resolve()
{
    $parameters = [];
    foreach ($this->parameters as $key => $value) {
        try {
            $value = $this->resolveValue($value);
            $parameters[$key] = $this->unescapeValue($value);
        } catch (ParameterNotFoundException $e) {
            $e->setSourceKey($key);

            throw $e;
        }
    }

    $this->parameters = $parameters;
