/**
 * Replaces parameter placeholders (%name%) by their values.
 *
 * @param mixed $value A value to substitute
 *
 * @return mixed The same value with all placeholder variables resolved if the given value is a string.
 *
 * @throws ParameterNotFoundException if a placeholder references a parameter that does not exist
 */
public function resolveValue($value)
{
    if (\is_array($value)) {
        $args = [];
        foreach ($value as $k => $v) {
            $args[\str_replace('%', '%%', $this->resolveValue($k))] = $this->resolveValue($v);
        }

        return $args;
    }

    if (!\is_string($value) || false === strpos($value, '%')) {
        return $value;
    }

    return $this->resolvePlaceholders($value);
}

private function resolvePlaceholders(string $value, array $resolving = [])
{
    $bag = $this;

    $resolved = preg_replace_callback('/%%|%([^%\s]+)%/', function ($match) use ($bag, $resolving, $value) {
        // skip anything that is not a proper parameter
        if (!isset($match[1])) {
            return '%%';
